n_ca_better = int(agg(D4, "comparison == 'C vs A' and metric == 'RMSE' and delta < 0 and hi < 0", None, "count", "{:.0f}", label="C vs A RMSE comparisons where hormones significantly improve (CI below 0)"))
n_ca_all = agg(D4, "comparison == 'C vs A' and metric == 'RMSE'", None, "count", "{:.0f}", label="number of C vs A RMSE comparisons")
n_ca_worse = agg(D4, "comparison == 'C vs A' and metric == 'RMSE' and delta > 0 and lo > 0", None, "count", "{:.0f}", label="C vs A comparisons where hormones significantly worsen (CI above 0)")
