add("**Findings.**")
add(f"1. *Phase alone gives a small gain, only for DRSP.* Ridge on set A: DRSP psychological {cA['drsp_psych']}, positive affect {cA['pos_affect']}, state anxiety {cA['stai']} (pooled).")
add(f"2. *Hormones do not improve prediction beyond phase.* Set C versus set A: among the {n_ca_all} paired RMSE comparisons ({FAC}) {n_ca_better} showed a significant improvement and {n_ca_worse} a significant deterioration. Example, pooled DRSP, ridge: change in RMSE {d4ci('pooled', 'drsp_psych', 'ridge', 'C vs A')} (positive = worse). Hormones alone (set B) never beat the baseline: significant improvements in {agg(D4, 'comparison == \"B vs baseline\" and metric == \"RMSE\" and delta < 0 and hi < 0', None, 'count', '{:.0f}', label='B vs baseline significant improvements')} of {agg(D4, 'comparison == \"B vs baseline\" and metric == \"RMSE\"', None, 'count', '{:.0f}', label='B vs baseline comparisons')}.")
claim(int(agg(D4, 'comparison == "B vs baseline" and metric == "RMSE" and delta < 0 and hi < 0', None, 'count', '{:.0f}')) == 0, "hormones alone never beat baseline")
add(f"3. *Trait scores carry the signal.* Set D, DRSP psychological, pooled: ridge {cD['drsp_psych']} (MAE {m4('pooled', 'drsp_psych', 'ridge', 'D', 'MAE')} versus baseline MAE {m4('pooled', 'drsp_psych', 'baseline', '-', 'MAE')}); anxiety {cD['stai']}; positive affect {cD['pos_affect']}. This matches the large person-level ICC.")
add(f"4. *PSST overlap is not the explanation.* Without PSST (set D2) pooled DRSP ridge gives {cD2} against {cD['drsp_psych']} with PSST; D was significantly better than D2 in {agg(D4, 'comparison == \"D vs D2\" and metric == \"RMSE\" and delta < 0 and hi < 0', None, 'count', '{:.0f}', label='D vs D2 significant improvements')} comparisons (BDI and BAI drive the skill; they too overlap conceptually with DRSP and STAI).")
add(f"5. *Model choice matters little:* for DRSP with set D (pooled) ridge, random forest and gradient boosting give {m4('pooled', 'drsp_psych', 'ridge', 'D', 'R2_oos', '{:+.3f}')}, {m4('pooled', 'drsp_psych', 'rf', 'D', 'R2_oos', '{:+.3f}')} and {m4('pooled', 'drsp_psych', 'gb', 'D', 'R2_oos', '{:+.3f}')}; trees on hormone-only sets are sometimes worse than the baseline (e.g. random forest, set B, anxiety, pooled: {m4ci('pooled', 'stai', 'rf', 'B')}), i.e. overfitting noise.")
lo_ = lambda t, m: ci(LO, dict(target=t, model=m), "R2_oos", "{:+.3f}", label=f"LOSO {t} {m}")
add(f"6. *Personal history helps far more than hormones* (leave-one-session-out, longitudinal sample, {val(LO, dict(target='drsp_psych', model='global mean'), 'n_rows', '{:.0f}', label='LOSO n rows')} rows, {val(LO, dict(target='drsp_psych', model='global mean'), 'n_women', '{:.0f}', label='LOSO n women')} women): ridge on set C without history R2_oos {lo_('drsp_psych', 'ridge C (no history)')} for DRSP, with the woman's mean from her other sessions added {lo_('drsp_psych', 'ridge C + personal mean')}; anxiety {lo_('stai', 'ridge C (no history)')} versus {lo_('stai', 'ridge C + personal mean')}.")
sh = df(SH).groupby("target").R2_oos.agg(["mean", "min", "max"]); sh_all = df(SH).R2_oos
add(f"7. *Leakage check:* with the target shuffled across rows (3 permutations x 3 targets, pooled {nn('pooled')}, ridge on set D) the skill was {calc('shuffled-target skill min', sh_all.min(), '{:+.4f}', SH, 'min of R2_oos over all permutations')} to {calc('shuffled-target skill max', sh_all.max(), '{:+.4f}', SH, 'max of R2_oos over all permutations')} (expected: about zero or slightly negative).\n")
claim(sh_all.max() < 0.01, "shuffled target skill ~0")
OF = "results/extOF_train_test.csv"; SCRIPT[OF] = "src/ext_OF_train_test_gap.py"
add(f"**Overfitting check: train versus test R2** (feature set D, pooled, {nn('pooled')}; leave-one-woman-out, nested CV, same folds and seeds as above; test predictions identical to the Phase 4 ones, largest difference {agg(OF, '', 'max_abs_pred_diff_vs_phase4', 'max', '{:.0e}', label='OF max |prediction difference| vs Phase 4')}). Train R2 = R2 of each fold's fitted model on its own training sessions (mean over the {val(OF, dict(target='drsp_psych', model='ridge'), 'n_women', '{:.0f}', label='OF number of folds')} folds, SD over folds); test R2 = pooled out-of-fold R2 (1 - SSE/SST over all held-out sessions: a single held-out woman has too few sessions for a per-fold R2); gap = train minus test, with a 95% CI from resampling women (paired).\n")
add("| Target | Model | Mean train R2 (SD over folds) | Test R2 [95% CI] | Gap [95% CI] |\n|---|---|---|---|---|")
for t in TS:
    for m in ["ridge", "rf", "gb"]:
        w = dict(target=t, model=m); add(f"| {TN[t]} | {m} | {val(OF, w, 'train_R2_mean', '{:.3f}', label=f'OF train R2 {t} {m}')} ({val(OF, w, 'train_R2_sd', '{:.3f}', label=f'OF train R2 SD {t} {m}')}) | {ci(OF, w, 'test_R2', '{:.3f}', lo='test_lo', hi='test_hi', label=f'OF test R2 {t} {m}')} | {ci(OF, w, 'gap', '{:+.3f}', lo='gap_lo', hi='gap_hi', label=f'OF gap {t} {m}')} |")
table("T-overfit", "train vs test R2 for ridge, random forest, gradient boosting (set D, pooled)", OF, "src/ext_OF_train_test_gap.py")
_g = df(OF); claim(bool((_g[_g.model.isin(["rf", "gb"])].gap_lo > 0).all()) and bool((_g[_g.model == "ridge"].gap_lo < 0).all()), "gap excludes 0 for forests/boosting and includes 0 for ridge")
add(f"\nThe flexible models fit the training women much better than the held-out women: the random forest and gradient boosting gaps are positive with intervals excluding 0 for all three targets (largest: {calc('OF largest gap', float(_g.gap.max()), '{:.3f}', OF, 'max gap')}, {_g.sort_values('gap').iloc[-1].model} on {TN[_g.sort_values('gap').iloc[-1].target]}), while ridge has a smaller gap whose interval includes 0 (range {calc('OF ridge gap min', float(_g[_g.model == 'ridge'].gap.min()), '{:+.3f}', OF, 'min ridge gap')} to {calc('OF ridge gap max', float(_g[_g.model == 'ridge'].gap.max()), '{:+.3f}', OF, 'max ridge gap')}). Yet the test R2 of the three models is similar (for DRSP {val(OF, dict(target='drsp_psych', model='ridge'), 'test_R2', '{:.3f}', label='OF test R2 ridge drsp')} / {val(OF, dict(target='drsp_psych', model='rf'), 'test_R2', '{:.3f}', label='OF test R2 rf drsp')} / {val(OF, dict(target='drsp_psych', model='gb'), 'test_R2', '{:.3f}', label='OF test R2 gb drsp')}): the larger gap did not translate into a visibly lower test score here (one possible reason, not tested: nested CV limits the flexibility of the forests), but the large training R2 would be a misleading measure of what to expect for a new woman. The honest number is the leave-one-woman-out test R2.\n")
